import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findPaymentsForOrder, uncapturedTotalCents } from '../src/services/payment-service.js';
import { PaymentRepository } from '../src/repositories/payment-repository.js';

const call = (fn, ...args) => new Promise((resolve, reject) =>
  fn(...args, (err, value) => (err ? reject(err) : resolve(value))));

test('findPaymentsForOrder finds the payment for an order', (t, done) => {
  findPaymentsForOrder(10, (err, rows) => {
    assert.equal(err, null);
    assert.equal(rows.length, 1);
    assert.equal(rows[0].amount_cents, 4200);
    done();
  });
});

test('findPaymentsForOrder returns the same rows as PaymentRepository.findByOrder', async () => {
  const expected = await new PaymentRepository().findByOrder(12);
  assert.deepEqual(await call(findPaymentsForOrder, 12), expected);
});

test('findPaymentsForOrder returns an empty list for an order with no payments', async () => {
  assert.deepEqual(await call(findPaymentsForOrder, 11), []);
});

test('uncapturedTotalCents sums uncaptured payments', (t, done) => {
  uncapturedTotalCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 9900);
    done();
  });
});

test('uncapturedTotalCents sums the rows from PaymentRepository.findUncaptured', async () => {
  const rows = await new PaymentRepository().findUncaptured();
  const expected = rows.reduce((sum, p) => sum + p.amount_cents, 0);
  assert.equal(await call(uncapturedTotalCents), expected);
});

