import { test } from 'node:test';
import assert from 'node:assert/strict';
import { UserRepository } from '../src/repositories/user-repository.js';
import { OrderRepository } from '../src/repositories/order-repository.js';

test('UserRepository.findActive matches the service behaviour', async () => {
  const users = await new UserRepository().findActive();
  assert.equal(users.length, 2);
});

test('UserRepository.findByEmail returns the matching user or null', async () => {
  const repo = new UserRepository();
  const user = await repo.findByEmail('grace@example.com');
  assert.equal(user.id, 2);
  assert.equal(user.name, 'Grace');
  assert.equal(await repo.findByEmail('nobody@example.com'), null);
});

test('UserRepository.findByEmail ignores soft-deleted users', async () => {
  assert.equal(await new UserRepository().findByEmail('alan@example.com'), null);
});

test('OrderRepository.findPaid matches the service behaviour', async () => {
  const orders = await new OrderRepository().findPaid();
  assert.equal(orders.length, 3);
});

test('OrderRepository.findQuotes returns only quote orders', async () => {
  const orders = await new OrderRepository().findQuotes();
  assert.deepEqual(orders.map((o) => o.id), [11]);
  assert.ok(orders.every((o) => o.status === 'quote'));
});

